/**
 * simulate-customer.ts
 * Simulates a customer paying a Settl invoice link from the command line.
 *
 * Usage:
 *   CUSTOMER_PRIVATE_KEY=0x... bun run scripts/simulate-customer.ts \
 *     "<pay link URL>" [--amount-override <micro-USDC>]
 *
 * Requires:
 *   - CUSTOMER_PRIVATE_KEY: EOA private key with Arc Testnet USDC
 *   - A pay link generated by the Settl merchant app
 *
 * Safety:
 *   - Refuses any chain other than Arc Testnet (chain ID 5042002)
 *   - Never touches mainnet
 *   - Reads CUSTOMER_PRIVATE_KEY from env only — never from args
 */

import { createPublicClient, createWalletClient, http, erc20Abi, parseAbi } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { arcTestnet } from 'viem/chains'

const ARC_TESTNET_CHAIN_ID = 5042002
const USDC_ADDRESS = '0x3600000000000000000000000000000000000000' as const
const ROUTER_ABI = parseAbi([
  'function pay(bytes32 invoiceId, address merchant, uint256 amount, uint256 deadline) external',
])

// ── Helpers ────────────────────────────────────────────────────────────────

function parseLink(url: string): {
  v: string; r: string; m: string; a: string
  i: string; d: string; c: string; n?: string; t?: string
} {
  const hash = url.includes('#') ? url.split('#')[1] : url
  const p = new URLSearchParams(hash)
  const get = (k: string) => p.get(k) ?? ''
  return { v: get('v'), r: get('r'), m: get('m'), a: get('a'), i: get('i'), d: get('d'), c: get('c'), n: p.get('n') ?? undefined, t: p.get('t') ?? undefined }
}

function validateLink(link: ReturnType<typeof parseLink>): void {
  if (link.v !== '1') throw new Error('Unsupported invoice version')
  const chainId = parseInt(link.c, 10)
  if (chainId !== ARC_TESTNET_CHAIN_ID) {
    throw new Error(`SAFETY: link is for chain ${chainId}, expected Arc Testnet ${ARC_TESTNET_CHAIN_ID}. Refusing.`)
  }
  if (!link.r || !/^0x[0-9a-fA-F]{40}$/.test(link.r)) throw new Error('Invalid router address')
  if (!link.m || !/^0x[0-9a-fA-F]{40}$/.test(link.m)) throw new Error('Invalid merchant address')
  if (!link.a || !/^\d+$/.test(link.a)) throw new Error('Invalid amount')
  if (!link.i || !/^0x[0-9a-fA-F]{64}$/.test(link.i)) throw new Error('Invalid invoice ID')
  const deadline = parseInt(link.d, 10)
  if (deadline <= Math.floor(Date.now() / 1000)) throw new Error('Invoice expired')
}

// ── Main ───────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2)
  if (args.length === 0) {
    console.error('Usage: CUSTOMER_PRIVATE_KEY=0x... bun run scripts/simulate-customer.ts "<pay link>" [--amount-override <micro-USDC>]')
    process.exit(1)
  }

  const url = args[0]
  const amountOverrideIdx = args.indexOf('--amount-override')
  const amountOverride = amountOverrideIdx !== -1 ? BigInt(args[amountOverrideIdx + 1]) : undefined

  const privateKey = process.env.CUSTOMER_PRIVATE_KEY as `0x${string}` | undefined
  if (!privateKey) {
    console.error('ERROR: CUSTOMER_PRIVATE_KEY env var not set')
    process.exit(1)
  }

  const link = parseLink(url)
  validateLink(link)

  const amount = amountOverride ?? BigInt(link.a)
  const routerAddress = link.r as `0x${string}`
  const merchantAddress = link.m as `0x${string}`
  const invoiceId = link.i as `0x${string}`
  const deadline = BigInt(link.d)

  // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-assignment
  const account = privateKeyToAccount(privateKey)

  const chain = { ...arcTestnet, id: ARC_TESTNET_CHAIN_ID, rpcUrls: { default: { http: ['https://rpc.testnet.arc.io'] }, public: { http: ['https://rpc.testnet.arc.io'] } } }
  const publicClient = createPublicClient({ chain, transport: http('https://rpc.testnet.arc.io') })
  const walletClient = createWalletClient({ account, chain, transport: http('https://rpc.testnet.arc.io') })

  console.log(`\n── Settl Customer Simulator ──────────────────────────────`)
  console.log(`Customer: ${account.address}`)
  console.log(`Merchant: ${merchantAddress}`)
  console.log(`Amount:   ${amount} micro-USDC = $${(Number(amount) / 1_000_000).toFixed(6)} USDC`)
  if (amountOverride) console.log(`          (overridden from link amount ${link.a})`)
  console.log(`Invoice:  ${invoiceId}`)
  console.log(`Router:   ${routerAddress}`)
  console.log(`Deadline: ${new Date(Number(deadline) * 1000).toISOString()}`)
  console.log()

  // Check balance
  const balance = await publicClient.readContract({ address: USDC_ADDRESS, abi: erc20Abi, functionName: 'balanceOf', args: [account.address] })
  console.log(`Balance:  ${balance} micro-USDC = $${(Number(balance) / 1_000_000).toFixed(6)} USDC`)
  if (balance < amount) {
    console.error(`ERROR: Insufficient balance (${balance} < ${amount})`)
    process.exit(1)
  }

  // Check allowance
  const allowance = await publicClient.readContract({ address: USDC_ADDRESS, abi: erc20Abi, functionName: 'allowance', args: [account.address, routerAddress] })
  console.log(`Allowance: ${allowance} micro-USDC`)

  // Approve if needed
  if (allowance < amount) {
    console.log(`\n[1/2] Approving ${amount} micro-USDC...`)
    const approveStart = Date.now()
    const approveTx = await walletClient.writeContract({ account, address: USDC_ADDRESS, abi: erc20Abi, functionName: 'approve', args: [routerAddress, amount], chain })
    console.log(`      approve tx: ${approveTx}`)
    await publicClient.waitForTransactionReceipt({ hash: approveTx })
    console.log(`      confirmed in ${Date.now() - approveStart}ms`)
  } else {
    console.log(`\n[skip] Allowance already sufficient`)
  }

  // Pay
  console.log(`\n[2/2] Calling router.pay()...`)
  const payStart = Date.now()
  const payTx = await walletClient.writeContract({
    account,
    chain,
    address: routerAddress,
    abi: ROUTER_ABI,
    functionName: 'pay',
    args: [invoiceId, merchantAddress, amount, deadline],
  })
  console.log(`      pay tx: ${payTx}`)
  const receipt = await publicClient.waitForTransactionReceipt({ hash: payTx })
  const elapsed = Date.now() - payStart
  console.log(`      confirmed in ${elapsed}ms (block ${receipt.blockNumber})`)
  console.log()

  if (receipt.status === 'success') {
    console.log(`✓ PAID — tx: ${payTx}`)
    console.log(`  elapsed from pay() submission: ${elapsed}ms`)
    console.log(`  explorer: https://explorer.testnet.arc.io/tx/${payTx}`)
  } else {
    console.error(`✗ FAILED — receipt status: ${receipt.status}`)
    process.exit(1)
  }
}

main().catch((err: unknown) => {
  console.error('Fatal:', err instanceof Error ? err.message : String(err))
  process.exit(1)
})
